-- Generated by scripts/build_compiled.py from src/fraudrules/rules/check-kiting/ck-002-deposit-then-drain.yaml. Do not edit.
-- CK-002 Check deposits withdrawn before they could have cleared
SELECT
  'CK-002' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 172800
WHERE
  (
    a.direction = 'out' AND a.channel IN ('cash', 'atm', 'wire', 'rtp', 'p2p')
  )
  AND (
    b.direction = 'in' AND b.channel = 'check' AND b.txn_type = 'deposit'
  )
GROUP BY
  a.id
HAVING
  (
    SUM(b.amount_cents) >= 250000
    AND MAX(a.amount_cents) * 100 >= SUM(b.amount_cents) * 70
  );
